style.css:
/* Apply dark rouge background to the entire Pinterest page */
body, html {
    background-color: #8B0000 !important; /* Dark rouge color */
}

/* Adjust main content background to match or contrast */
div, section, header, footer {
    background-color: #8B0000 !important; /* Ensure uniformity */
}

/* Adjust text color for readability */
* {
  color: #ffffff !important; /* White text */
}
